import{storedProjection}from"#harness/session-machine/view.js";import{isActiveTaskRun,readTaskTable}from"#execution/tasks/table.js";import{isWorkflowMessage}from"#execution/session-inbox/inbox.js";import{isAgentSessionMessage,runMessageBatchBudget}from"#execution/tools/workflow/messages.js";import{findBlockingWorkflowToolRun,isInboxToolResultFromRecordedWorkflowToolRun}from"#harness/workflow-tool-runs.js";import{isTaskRunMessage}from"#execution/tasks/session.js";import{deliverWorkflowRelay}from"#execution/tools/workflow/owner.js";import{withdrawFinishedRunQuestionsStep,withdrawWorkflowToolRunQuestionStep}from"#execution/tools/workflow/withdraw-step.js";import{workflowAskPayload,workflowToolRunOutcomeToToolResult}from"#execution/tools/workflow/owner-inbox.js";import{runProxySubagentEventStep}from"#subagents/event-proxy-step.js";function isAppliedRunMessage(e){return isAgentSessionMessage(e)||e.kind===`report`||isTaskRunMessage(e)}function takeLeadingAppliedRunMessages(e,t=runMessageBatchBudget()){return e.takeLeading(e=>isWorkflowMessage(e)&&isAppliedRunMessage(e)&&t(e))}async function handleWorkflowToolRunMessage(e){let{message:t}=e;switch(t.kind){case`started`:case`reply`:case`usage`:return;case`outcome`:return await handleWorkflowToolRunOutcome({...e,message:t});case`request`:await handleWorkflowToolRunRequest({...e,message:t});return;case`withdraw`:await handleWorkflowToolRunWithdraw({...e,message:t});return}}async function handleWorkflowToolRunOutcome(e){let{cursor:t,message:n}=e,r=t.sessionState.snapshot.session.state;if(findBlockingWorkflowToolRun(r,n.from.callId,n.from.turnId)?.address.runId!==n.from.runId)return;let i=workflowToolRunOutcomeToToolResult(n);if(isInboxToolResultFromRecordedWorkflowToolRun(r,i)){if(t.sessionState.hasProxyInputRequests){let{runId:e}=n.from;await t.advance(t=>withdrawFinishedRunQuestionsStep({...t,runId:e}))}return i}}async function handleWorkflowToolRunRequest(e){let{cursor:t,message:n}=e,{runId:r,taskId:i}=n.from,a=t.sessionState.snapshot.session.state;if(i!==void 0&&(!isActiveTaskRun(readTaskTable(a),i,r)||storedProjection(a).view?.tasks[i]?.status===`ended`))return;let{request:o}=n;o.kind===`relay`?await deliverWorkflowRelay({...n,request:o},async()=>{await t.advance(e=>runProxySubagentEventStep({hookPayload:o.event,runId:r,...e}))}):await t.advance(e=>runProxySubagentEventStep({hookPayload:workflowAskPayload({...n,request:o}),runId:r,workflowAsk:createWorkflowAskRoute(o),...e}))}async function handleWorkflowToolRunWithdraw(e){let{cursor:t,message:n}=e;await t.advance(e=>withdrawWorkflowToolRunQuestionStep({...e,control:n.control,requestId:n.replyTo,runId:n.from.runId}))}function createWorkflowAskRoute(e){return{control:e.control}}export{handleWorkflowToolRunMessage,isAppliedRunMessage,takeLeadingAppliedRunMessages};